(48831, 'esMX', 'Comandante Texlaz', '', '', '', '', '', '', '', '', 25549),
(48830, 'esMX', 'Inquisidor Vethroz', '', '', '', '', '', '', '', '', 25549),
(48829, 'esMX', 'Señor de cólera Yarez', '', '', '', '', '', '', '', '', 25549),
