UPDATE `quest_template_locale` SET `LogDescription`='Preséntate ante el Alto señor supremo Colmillosauro en el Fuerte Grommash, en Orgrimmar.', `QuestDescription`='Se le ordena a todos los miembros aptos de la Horda que se presenten ante el Alto señor supremo Colmillosauro en el Fuerte Grommash.$B$B El Alto señor supremo Colmillosauro necesita tu ayuda para preparar el glorioso ataque a las Tierras Altas Crepusculares contra nuestros dos enemigos: la Alianza y el Martillo Crepuscular.$B$BReúnete con él en el Fuerte Grommash en el centro del Valle de la Fuerza, en Orgrimmar.$B$B¡El destino aguarda!', `VerifiedBuild`=25549 WHERE (`ID`=28717 AND `locale`='esMX');
UPDATE `quest_template_locale` SET `LogDescription`='Habla con el rey Anduin Wrynn en el Castillo de Ventormenta, en Ventormenta.', `QuestDescription`='Por orden de su alteza real, el rey Anduin Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse en la Sala del Trono, en el Castillo de Ventormenta.$B$BEl rey Wrynn necesita un héroe digno de confianza y que haya demostrado su valía para una misión de la mayor importancia.$B$BEl Castillo de Ventormenta está situado en la zona este de la Ciudad de Ventormenta.$B$B¡Por la gloria y el honor de la Alianza!', `VerifiedBuild`=25549 WHERE (`ID`=28716 AND `locale`='esMX');
