UPDATE `quest_template_locale` SET `QuestDescription`='Mientras la Plaga invadía Stratholme como una peste, los caballeros de la Mano de plata elaboraban agua bendita para utilizarla contra los atacantes. La almacenaron en cajones, junto con otros suministros vitales, y los distribuyeron por toda la ciudad. Por desgracia, los ciudadanos se convirtieron en refuerzos de la Plaga antes de poder usar los suministros.$b$bEsos cajones de suministros nos serían de gran ayuda. Tráeme un vial de agua bendita de Stratholme, tenemos que reproducirla en masa.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=27352 AND `locale`='esMX');
