UPDATE `quest_template_locale` SET `QuestDescription`='La furia de Mankrik por su difunta mujer me preocupa, $c.$B$BLos jabaespines de Horado Rajacieno son mucho más despiadados y odiosos de lo que Mankrik jamás podría imaginar.$B$BDeberías viajar al sur de aquí y hablar con mi viejo amigo Auld Picopiedra. Se esfuerza por poner fin a esta locura antes de que la tierra sufra más en su estado ya débil de por sí.', `VerifiedBuild`=25549 WHERE (`ID`=26908 AND `locale`='esMX');
