UPDATE `quest_template_locale` SET `LogDescription`='Recupera el cristal de Ata''mal y dáselo a la imagen del Príncipe del Nexo Haramad en La Flecha de la Tormenta, en Tormenta Abisal.', `QuestDescription`='Ahora que tenemos los datos del primer y segundo puntos, sé con certeza que el cristal está en la cima de las Ruinas de Farahlon, al noreste.$B$BPor desgracia, los datos indican que el cristal está en movimiento, lo que significa que alguien lo ha encontrado; probablemente sea la Legión Ardiente.$B$BTe recomiendo que lleves algunos amigos, por si acaso.$B$BMata al demonio que tiene el cristal y llévaselo al Príncipe del Nexo Haramad.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10276 AND `locale`='esMX');
UPDATE `quest_template_locale` SET `QuestDescription`='He vuelto a calibrar el aparato de triangulación con la información que trajiste del primer punto. Para encontrar el segundo, usa el mismo procedimiento.$B$BLo único que puedo decirte es que está lejos y hacia el oeste.$B$BCuando lo localices, habla con el comerciante de viento Tuluman, que es agente del Príncipe del Nexo. Se hace pasar por un mercader de armas junto al puente que lleva a la isla de Forja de Maná Ara.', `PortraitGiverText`='', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10275 AND `locale`='esMX');
