UPDATE `quest_template_locale` SET `LogDescription`='Entrega el equipo de análisis a la Imagen del Príncipe del Nexo Haramad en La Flecha de la Tormenta, en Tormenta Abisal.', `QuestDescription`='El Príncipe del Nexo Haramad me ha indicado que desea que estos bienes le sean devueltos personalmente con la mayor brevedad. Te agradecería que te encargases de llevárselos en mi lugar.$B$BObtener audiencia con el Príncipe del Nexo es un gran honor; seguro que le gustará oír de tus aventuras en Tormenta Abisal.$B$BSu cámara está en la cima de La Flecha de la Tormenta, hacia el norte. Suele estar presente en forma de holograma; cuando llegues, habla con él.', `VerifiedBuild`=25549 WHERE (`ID`=10268 AND `locale`='esMX');
